import hashlib, json
from pathlib import Path
root = Path('/workspace')
if '${_RELEASE_APPROVED}' != 'true' or '$COMMIT_SHA' != '36bb5d925305ab4046e08d4dae7372058b1c0a41' or '$PROJECT_ID' != 'repaido':
    raise SystemExit('Exact approved release/project required before any build work.')
manifest_path = root / 'release_support/reviewed-source.json'
raw = manifest_path.read_bytes()
if hashlib.sha256(raw).hexdigest() != '00aa3ae5108dd029db47a5a7721e0487311cd562a02edaa3bc5c56e8fe5cc267':
    raise SystemExit('Reviewed source manifest hash mismatch.')
manifest = json.loads(raw)
if manifest['commit'] != '36bb5d925305ab4046e08d4dae7372058b1c0a41' or manifest['deployed_baseline'] != '0bc8da6a22869d30a6cabd91782d3ac15d04570c':
    raise SystemExit('Reviewed source identity mismatch.')
for p in root.rglob('*'):
    if p.is_symlink():
        raise SystemExit('Linked files are forbidden in reviewed build source.')
actual = {p.relative_to(root).as_posix() for p in root.rglob('*') if p.is_file()}
if actual != set(manifest['files']) | {'release_support/reviewed-source.json'}:
    raise SystemExit('Uploaded source inventory differs from reviewed snapshot.')
for name, expected in manifest['files'].items():
    if hashlib.sha256((root / name).read_bytes()).hexdigest() != expected:
        raise SystemExit('Reviewed source digest mismatch: ' + name)
print('Exact reviewed source verified:', '36bb5d925305ab4046e08d4dae7372058b1c0a41', 'baseline', '0bc8da6a22869d30a6cabd91782d3ac15d04570c')
